package com.example.controllers;
import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.example.dtos.*; import com.example.services.PagamentoService;
@RestController @RequestMapping("/pagamentos") public class PagamentoController {private final PagamentoService service;public PagamentoController(PagamentoService service){this.service=service;}@GetMapping public List<PagamentoResponseDTO> listar(){return service.listarTodos();}@GetMapping("/{id}") public ResponseEntity<PagamentoResponseDTO> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));}@PostMapping public ResponseEntity<PagamentoResponseDTO> criar(@RequestBody PagamentoRequestDTO d){return ResponseEntity.ok(service.criar(d));}@PostMapping("/{id}/aprovar") public ResponseEntity<PagamentoResponseDTO> aprovar(@PathVariable Long id){return ResponseEntity.ok(service.aprovar(id));}@PostMapping("/{id}/recusar") public ResponseEntity<PagamentoResponseDTO> recusar(@PathVariable Long id){return ResponseEntity.ok(service.recusar(id));}@PostMapping("/{id}/cancelar") public ResponseEntity<PagamentoResponseDTO> cancelar(@PathVariable Long id){return ResponseEntity.ok(service.cancelar(id));}}
